from pathlib import Path
p=Path('deep-shift-visual/scripts/AudioManager.gd')
p.write_text('''extends Node\nconst MIX_RATE: float = 44100.0\nvar player: AudioStreamPlayer\nvar generator: AudioStreamGenerator\nvar playback: AudioStreamGeneratorPlayback\nvar rng_state: int = 123456789\nfunc _ready() -> void:\n    generator = AudioStreamGenerator.new()\n    generator.mix_rate = MIX_RATE\n    generator.buffer_length = 0.5\n    player = AudioStreamPlayer.new()\n    player.stream = generator\n    add_child(player)\n    player.play()\n    playback = player.get_stream_playback() as AudioStreamGeneratorPlayback\nfunc play(id: String, pitch: float = 1.0) -> void:\n    if playback == null: return\n    var spec := _spec(id)\n    var duration: float = float(spec.get("duration",0.12))\n    var f0: float = float(spec.get("f0",220.0))*pitch\n    var f1: float = float(spec.get("f1",f0))*pitch\n    var amp: float = float(spec.get("amp",0.25))\n    var shape: String = str(spec.get("shape","sine"))\n    var count: int = int(MIX_RATE*duration)\n    var frames := PackedVector2Array(); frames.resize(count)\n    for i in range(count):\n        var tt := float(i)/MIX_RATE\n        var phase := float(i)/float(max(1,count-1))\n        var freq := lerpf(f0,f1,phase)\n        var env := pow(1.0-phase,1.7)\n        var sample := _wave(shape,freq,tt)*amp*env\n        frames[i] = Vector2(sample,sample)\n    playback.clear_buffer(); playback.push_buffer(frames)\nfunc _wave(shape:String,freq:float,tt:float)->float:\n    var s := sin(TAU*freq*tt)\n    match shape:\n        "square": return 1.0 if s>=0.0 else -1.0\n        "triangle": return asin(s)*(2.0/PI)\n        "crunch":\n            rng_state=int((1103515245*rng_state+12345)&0x7fffffff)\n            var n := (float(rng_state)/1073741823.5)-1.0\n            return clamp(s*0.65+n*0.35,-1.0,1.0)\n        _: return s\nfunc _spec(id:String)->Dictionary:\n    match id:\n        "dig": return {"duration":0.07,"f0":95.0,"f1":55.0,"amp":0.30,"shape":"crunch"}\n        "ore": return {"duration":0.16,"f0":620.0,"f1":980.0,"amp":0.22,"shape":"sine"}\n        "pulse": return {"duration":0.18,"f0":260.0,"f1":95.0,"amp":0.25,"shape":"triangle"}\n        "charge": return {"duration":0.22,"f0":80.0,"f1":42.0,"amp":0.32,"shape":"crunch"}\n        "hurt": return {"duration":0.12,"f0":125.0,"f1":65.0,"amp":0.32,"shape":"square"}\n        "boss_warning": return {"duration":0.30,"f0":72.0,"f1":48.0,"amp":0.30,"shape":"square"}\n        "extract": return {"duration":0.34,"f0":330.0,"f1":880.0,"amp":0.23,"shape":"sine"}\n        _: return {"duration":0.10,"f0":220.0,"f1":180.0,"amp":0.20,"shape":"sine"}\n''')
